INSERT OR IGNORE INTO questions (topic, age, tag, question_text, normalized_question, option_a, option_b, option_c, option_d, correct_index, explanation, is_active, created_at, updated_at) VALUES ('domeo', 'kho', 'đố mẹo', 'Hai người cha và hai người con đi câu cá, mỗi người câu được một con. Vì sao họ chỉ có ba con cá?', 'hai người cha và hai người con đi câu cá, mỗi người câu được một con. vì sao họ chỉ có ba con cá?', 'Một người không câu được', 'Họ là ông, bố và con', 'Một con cá bị mất', 'Họ chia chung một con', 1, 'Đúng rồi, ba người là ông, bố và con; người bố vừa là con của ông vừa là cha của bé.', 1, unixepoch(), unixepoch());
